/**
 * Дни приёма врачей — то, что клиника знает, а агент до сих пор не знал.
 *
 * Живой диалог: «Здравствуйте, подскажите, работаете ли вы в выходные дни? И
 * сколько у вас стоит приём?» Агент ответил верно про клинику («в субботу с
 * 09:00 до 21:00») и назвал цены ОБОИХ остеопатов — а в субботу принимает
 * только одна из них. Администратору пришлось писать вслед: «в субботу
 * принимает Разият Ризвановна».
 *
 * График клиники и график врача — разные вещи, и путать их дороже всего в
 * ответе на прямой вопрос: человек запоминает имя и приезжает не в тот день.
 */

/** 1 = понедельник … 7 = воскресенье (ISO-8601), как в ClinicSchedule. */
export const WEEKDAY_NAMES: Record<number, string> = {
  1: "понедельник",
  2: "вторник",
  3: "среда",
  4: "четверг",
  5: "пятница",
  6: "суббота",
  7: "воскресенье",
};

/**
 * «В субботу», а не «в суббота».
 *
 * Мелочь, которая читается как машинный перевод: пациент видит «В пятница
 * принимает…» и понимает, что говорит с программой. Предлог тоже разный —
 * «во вторник».
 */
export const WEEKDAY_WHEN: Record<number, string> = {
  1: "в понедельник",
  2: "во вторник",
  3: "в среду",
  4: "в четверг",
  5: "в пятницу",
  6: "в субботу",
  7: "в воскресенье",
};

const WEEKDAY_WORDS: { day: number; re: RegExp }[] = [
  { day: 1, re: /(?<!\p{L})понедельник\p{L}*(?!\p{L})/iu },
  { day: 2, re: /(?<!\p{L})вторник\p{L}*(?!\p{L})/iu },
  { day: 3, re: /(?<!\p{L})сред[ауые]\p{L}*(?!\p{L})/iu },
  { day: 4, re: /(?<!\p{L})четверг\p{L}*(?!\p{L})/iu },
  { day: 5, re: /(?<!\p{L})пятниц\p{L}*(?!\p{L})/iu },
  { day: 6, re: /(?<!\p{L})суббот\p{L}*(?!\p{L})/iu },
  { day: 7, re: /(?<!\p{L})воскресень\p{L}*|воскресен\p{L}*(?!\p{L})/iu },
];

/**
 * Дни недели, названные в вопросе.
 *
 * «Выходные» — это суббота и воскресенье: так говорят люди, и именно так был
 * задан вопрос, с которого всё началось.
 */
export function daysAsked(text: string): number[] {
  const found = new Set<number>();
  for (const { day, re } of WEEKDAY_WORDS) if (re.test(text)) found.add(day);
  if (/(?<!\p{L})выходн\p{L}*(?!\p{L})/iu.test(text)) {
    found.add(6);
    found.add(7);
  }
  return [...found].sort((a, b) => a - b);
}

/**
 * «Сегодня», «завтра», «послезавтра» — дни недели по часам клиники.
 *
 * Только для строки «кто в этот день принимает» к записи: «на сегодня есть
 * окошки?» (живой диалог 6 октября) — это вопрос и про врачей этого дня. В
 * ветку прямых вопросов о расписании не идёт: «сегодня» там встречается и в
 * «сегодня у меня запись», и в «я сегодня опоздаю».
 */
export function relativeDaysAsked(text: string, now: Date, tz: string): number[] {
  const weekday = (offsetDays: number) => {
    const name = new Intl.DateTimeFormat("en-GB", { timeZone: tz, weekday: "short" }).format(
      new Date(now.getTime() + offsetDays * 86_400_000),
    );
    return ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].indexOf(name) + 1;
  };
  const found = new Set<number>();
  if (/(?<!\p{L})сегодня(?!\p{L})/iu.test(text)) found.add(weekday(0));
  if (/(?<!\p{L})завтра(?!\p{L})/iu.test(text)) found.add(weekday(1));
  if (/(?<!\p{L})послезавтра(?!\p{L})/iu.test(text)) found.add(weekday(2));
  return [...found].sort((a, b) => a - b);
}

/**
 * Одна ли это специальность. В справочнике клиники она записана руками и
 * по-разному: «Остеопат» у одного врача и «врач остеопат» у другого. При
 * дословном сравнении агент не находил замены и говорил «в субботу приёма нет»,
 * хотя в субботу принимает второй остеопат (демо-прогон 12 октября).
 * «Врач», «доктор» и регистр смысла не меняют; основа слова — первые шесть букв.
 */
export function sameSpecialty(a: string | null | undefined, b: string | null | undefined): boolean {
  const key = (s: string | null | undefined) =>
    (s ?? "")
      .toLowerCase()
      .replace(/ё/g, "е")
      .split(/[^\p{L}]+/u)
      .filter((w) => w.length >= 3 && !/^(?:врач|доктор|специалист)$/u.test(w))
      .map((w) => w.slice(0, 6))
      .sort()
      .join(" ");
  const ka = key(a);
  return ka.length > 0 && ka === key(b);
}

export interface StaffDays {
  name: string;
  specialty?: string | null;
  /** Пустой список — дни не заданы: об этом враче в такой ответ не идём. */
  workdays: number[];
}

/**
 * Кто принимает в названные дни.
 *
 * Врачи без заданных дней в ответ не попадают ни в одну сторону: пустая
 * настройка не значит «не работает», и утверждать за неё нельзя.
 */
export function whoWorks(staff: StaffDays[], days: number[]): { works: StaffDays[]; off: StaffDays[] } {
  const known = staff.filter((s) => s.workdays.length > 0);
  return {
    works: known.filter((s) => days.some((d) => s.workdays.includes(d))),
    off: known.filter((s) => !days.some((d) => s.workdays.includes(d))),
  };
}

/** Названный в вопросе врач — по первым буквам имени, чтобы падежи не мешали. */
export function staffAsked<T extends { name: string }>(text: string, staff: T[]): T | null {
  const norm = text.toLowerCase().replace(/ё/g, "е");
  return (
    staff.find((s) =>
      s.name
        .toLowerCase()
        .replace(/ё/g, "е")
        .split(/\s+/)
        .filter((w) => w.length >= 4)
        .some((w) => norm.includes(w.slice(0, 5))),
    ) ?? null
  );
}

/**
 * Врач назван так, что ошибиться нельзя: совпал ровно один.
 *
 * «Скажите пожалуйста к Ирине Алилгаджиевне когда есть окошко?» — к кому и,
 * значит, на что записываться, человек уже сказал, а агент переспросил «на
 * какую услугу». Но одно имя «Ирина» у клиники носят двое — остеопат и
 * БОС-терапевт, — и там услуга остаётся неизвестной: угадывать врача нельзя.
 */
export function uniqueStaffAsked<T extends { name: string }>(text: string, staff: T[]): T | null {
  const norm = text.toLowerCase().replace(/ё/g, "е");
  /**
   * Сколько слов имени нашлось в тексте.
   *
   * Живой диалог: «хотела детей записать к Ирине Алункачевой». Фамилия названа,
   * и ошибиться нельзя — но по ОДНОМУ совпавшему слову подходили двое: Ирина
   * Алункачева и Ирина Омарова. Врач считался неназванным, и агент переспрашивал
   * «на какую услугу записываемся», хотя человек уже всё сказал.
   *
   * Поэтому сравниваем по числу совпавших слов: «Ирине Алункачевой» — два слова
   * у одной и одно у другой. Ровно то же правило, которым ассистент
   * администратора различает двух Ирин.
   */
  const score = (name: string) =>
    name
      .toLowerCase()
      .replace(/ё/g, "е")
      .split(/\s+/)
      .filter((w) => w.length >= 4)
      // Основа короче слова: «Ирина» должна найтись и в «Ирине», «Ириной».
      .filter((w) => norm.includes(w.slice(0, Math.min(5, w.length - 1)))).length;

  /**
   * Инициал после имени: «к Ирине А.», «Ирина А», «Разият Р.».
   *
   * Живой диалог 4 октября: «на 12 октября к Ирине А. есть окошко?». Ирин двое,
   * совпавшее слово одно у обеих — врач считался неназванным, агент спросил «на
   * какую услугу», а потом сам выбрал услугу другого врача. Буква после имени —
   * это фамилия или отчество, и у Ирины Алилгаджиевны она «А», а у Ирины
   * Омаровой — «О». Засчитываем инициал, только если он стоит сразу за
   * совпавшим словом имени и совпадает с началом другого слова того же имени.
   */
  const initialHits = (name: string) => {
    const parts = name.toLowerCase().replace(/ё/g, "е").split(/\s+/).filter((w) => w.length >= 2);
    let hits = 0;
    for (const part of parts.filter((w) => w.length >= 4)) {
      const stem = part.slice(0, 4);
      // Флаг i нужен для основы («Ирине»), но он же складывает регистр у \p{Lu} —
      // заглавность буквы проверяем отдельно ниже.
      const re = new RegExp(`(?<!\\p{L})${stem}\\p{L}*\\s+(\\p{L})\\.?(?!\\p{L})`, "giu");
      for (const m of text.replace(/ё/g, "е").replace(/Ё/g, "Е").matchAll(re)) {
        const letter = m[1].toLowerCase();
        // Буква должна быть ЗАГЛАВНОЙ в исходном тексте: «к Ирине а есть окошко» — союз, не инициал.
        if (m[1] !== m[1].toUpperCase()) continue;
        if (parts.some((p) => p !== part && p.startsWith(letter))) hits += 1;
      }
    }
    return Math.min(hits, 1);
  };

  const scored = staff
    .map((s) => {
      const words = score(s.name);
      return { s, hits: words > 0 ? words + initialHits(s.name) : 0 };
    })
    .filter((x) => x.hits > 0);
  if (scored.length === 0) return null;
  const best = Math.max(...scored.map((x) => x.hits));
  const top = scored.filter((x) => x.hits === best);
  // Ровно столько же совпало у нескольких — угадывать нельзя («к Ирине»).
  return top.length === 1 ? top[0].s : null;
}

/** Назван ли в тексте хоть кто-то из сотрудников — пусть и двояко («к Ирине»). */
function staffMentioned(text: string, staff: { name: string }[]): boolean {
  const norm = text.toLowerCase().replace(/ё/g, "е");
  return staff.some((s) =>
    s.name
      .toLowerCase()
      .replace(/ё/g, "е")
      .split(/\s+/)
      .filter((w) => w.length >= 4)
      .some((w) => norm.includes(w.slice(0, Math.min(5, w.length - 1)))),
  );
}

/**
 * Врач из САМОЙ СВЕЖЕЙ реплики, где врача называли (реплики — от новых к
 * старым). Названо двояко — врач неизвестен, а не взят из реплики постарше.
 *
 * Живой прогон 5 октября: «хочу ещё раз к Ирине записаться» → «В четверг после
 * обеда» — и ответ «Да, Разият Ризвановна принимает в четверг». «К Ирине»
 * двояко (Ирин две), и поиск ушёл в старую реплику про Разият: человеку назвали
 * чужого врача.
 */
export function lastNamedStaff<T extends { name: string }>(newestFirst: string[], staff: T[]): T | null {
  /**
   * Свежая реплика назвала врача двояко — круг сужен до подходящих. Реплика
   * постарше, где назван однозначно ОДИН из них, круг разрешает: «к Ирине
   * Алилгаджиевне» → «А Ирина в субботу принимает?» — это всё та же Ирина. Врач
   * вне круга («у Разият» вчера) — не ответ на сегодняшнее «к Ирине».
   */
  let circle: T[] | null = null;
  for (const text of newestFirst) {
    if (!staffMentioned(text, staff)) continue;
    const unique = uniqueStaffAsked(text, staff);
    if (unique) return !circle || circle.includes(unique) ? unique : null;
    circle ??= staff.filter((s) => staffMentioned(text, [s]));
  }
  return null;
}

/**
 * Вопрос без слов о днях недели — для поиска услуги.
 *
 * «А в воскресенье можно на остеопатию?» не находило услугу: слово
 * «воскресенье» длинное и перевешивало «остеопатию» в доле совпадения.
 * Услугу ищем по тому, что осталось после дня.
 */
export function withoutDays(text: string): string {
  let out = text;
  for (const { re } of WEEKDAY_WORDS) out = out.replace(new RegExp(re.source, "giu"), " ");
  return out.replace(/(?<!\p{L})выходн\p{L}*(?!\p{L})/giu, " ").replace(/\s{2,}/g, " ").trim();
}

/**
 * Ответ утверждает, что врач принимает в день, когда он не принимает.
 *
 * Проверка, а не генерация: отвечает по-прежнему модель — она умеет ответить
 * сразу на два вопроса («работаете в выходные и сколько стоит»), — а код
 * ловит единственную ошибку, из-за которой человек приезжает зря.
 *
 * Смотрим по предложениям: врач и день должны стоять рядом. Отрицание
 * («не принимает», «выходной») снимает подозрение — это и есть верный ответ.
 */
export function wrongWorkday(
  answer: string,
  staff: StaffDays[],
  /**
   * Дни из ВОПРОСА пациента.
   *
   * Спросили «работаете ли в выходные и сколько стоит приём?» — и ответ
   * «взрослый приём 8000 ₽, ведёт Ирина Алилгаджиевна» неверен целиком: в
   * субботу она не принимает. Дня недели в этом предложении нет, и разбор по
   * предложениям такую ошибку не видит — а пациент запомнит имя.
   */
  askedDays: number[] = [],
): string | null {
  const known = staff.filter((s) => s.workdays.length > 0);
  if (known.length === 0) return null;

  if (askedDays.length > 0) {
    for (const sentence of answer.split(/(?<=[.!?\n])/)) {
      if (/(?:не\s+принима|не\s+работа|выходн|не\s+веду|не\s+ведёт|не\s+ведет)/iu.test(sentence)) continue;
      const named = staffAsked(sentence, known);
      if (!named) continue;
      const bad = askedDays.filter((d) => !named.workdays.includes(d));
      if (bad.length === askedDays.length) {
        return `${named.name} — ${bad.map((d) => WEEKDAY_NAMES[d]).join(", ")}`;
      }
    }
  }

  for (const sentence of answer.split(/(?<=[.!?\n])/)) {
    if (/(?:не\s+принима|не\s+работа|выходн|не\s+веду|не\s+ведёт|не\s+ведет)/iu.test(sentence)) continue;
    const days = daysAsked(sentence);
    if (days.length === 0) continue;
    const named = staffAsked(sentence, known);
    if (!named) continue;
    const bad = days.filter((d) => !named.workdays.includes(d));
    if (bad.length > 0) {
      return `${named.name} — ${bad.map((d) => WEEKDAY_NAMES[d]).join(", ")}`;
    }
  }
  return null;
}

/**
 * Ответила ли модель про названный день.
 *
 * «Работаете ли вы в выходные дни? И сколько у вас стоит приём?» — модель
 * ответила только про цены, а про выходные не сказала ничего. Просьба в
 * промпте «ответь на каждую часть вопроса» помогает не всегда, и человек
 * остаётся без ответа на свой первый вопрос.
 *
 * Поэтому проверяем и дописываем факт, а не подменяем ответ: то, что модель
 * сказала про цены, остаётся целиком.
 */
export function daysAnswered(answer: string, days: number[]): boolean {
  const said = daysAsked(answer);
  return days.every((d) => said.includes(d));
}
